<template><div class="admin-page"><div class="admin-page__header"><h2>用户反馈</h2><el-button :icon="Download" @click="exportCsv">导出 CSV</el-button></div><div class="admin-toolbar"><el-radio-group v-model="status" @change="search"><el-radio-button label="">全部</el-radio-button><el-radio-button label="pending">待处理</el-radio-button><el-radio-button label="processing">处理中</el-radio-button><el-radio-button label="resolved">已处理</el-radio-button></el-radio-group></div><div class="admin-panel"><el-table :data="records"><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="user_name" label="用户" width="110"/><el-table-column prop="content" label="反馈内容" show-overflow-tooltip/><el-table-column prop="contact" label="联系方式" width="150"/><el-table-column prop="status" label="状态" width="100"/><el-table-column prop="create_time" label="提交时间" width="180"/><el-table-column label="操作" width="100"><template #default="s"><el-button link type="primary" @click="open(s.row)">处理</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="load" style="margin-top:16px;justify-content:flex-end"/></div><el-dialog v-model="dialog" title="处理反馈" width="620px"><el-alert :title="current?.content" type="info" :closable="false" style="margin-bottom:18px"/><el-form label-width="90px"><el-form-item label="处理状态"><el-select v-model="form.status" style="width:100%"><el-option label="待处理" value="pending"/><el-option label="处理中" value="processing"/><el-option label="已处理" value="resolved"/></el-select></el-form-item><el-form-item label="用户回复"><el-input v-model="form.adminReply" type="textarea" :rows="3"/></el-form-item><el-form-item label="内部备注"><el-input v-model="form.internalNote" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{Download}from'@element-plus/icons-vue';import{ElMessage}from'element-plus';import request from '@/utils/request';import'./admin.css';const status=ref(''),page=ref(1),total=ref(0),records=ref<any[]>([]),dialog=ref(false),current=ref<any>();const form=reactive({status:'pending',adminReply:'',internalNote:''});const load=async()=>{const r:any=await request.get('/api/admin/feedbacks',{params:{page:page.value,pageSize:20,status:status.value||undefined}});records.value=r.records;total.value=r.total};const search=()=>{page.value=1;load()};const open=(row:any)=>{current.value=row;form.status=row.status||'pending';form.adminReply=row.admin_reply||'';form.internalNote=row.internal_note||'';dialog.value=true};const save=async()=>{await request.put(`/api/admin/feedbacks/${current.value.id}`,form);ElMessage.success('反馈已更新');dialog.value=false;load()};const exportCsv=()=>fetch('/api/admin/export/feedbacks',{headers:{Authorization:`Bearer ${localStorage.getItem('token')}`}}).then(r=>r.blob()).then(b=>{const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='feedbacks.csv';a.click()});onMounted(load);</script>
